CREATE TABLE "Favorite"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"mediaTitleId" TEXT,"channelId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Favorite_pkey" PRIMARY KEY("id"));
CREATE TABLE "WatchProgress"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"mediaTitleId" TEXT,"episodeId" TEXT,"channelId" TEXT,"positionSec" INTEGER NOT NULL DEFAULT 0,"durationSec" INTEGER,"completed" BOOLEAN NOT NULL DEFAULT false,"lastDeviceId" TEXT,"lastWatchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WatchProgress_pkey" PRIMARY KEY("id"));
CREATE TABLE "SearchHistory"("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"query" TEXT NOT NULL,"normalizedQuery" TEXT NOT NULL,"searchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SearchHistory_pkey" PRIMARY KEY("id"));
CREATE TABLE "PopularityDaily"("id" TEXT NOT NULL,"mediaTitleId" TEXT NOT NULL,"day" DATE NOT NULL,"starts" INTEGER NOT NULL DEFAULT 0,"completions" INTEGER NOT NULL DEFAULT 0,"uniqueViewers" INTEGER NOT NULL DEFAULT 0,"score" DOUBLE PRECISION NOT NULL DEFAULT 0,"CONSTRAINT_PLACEHOLDER" INTEGER,CONSTRAINT "PopularityDaily_pkey" PRIMARY KEY("id"));ALTER TABLE "PopularityDaily" DROP COLUMN "CONSTRAINT_PLACEHOLDER";
CREATE UNIQUE INDEX "Favorite_userId_mediaTitleId_key" ON "Favorite"("userId","mediaTitleId");CREATE UNIQUE INDEX "Favorite_userId_channelId_key" ON "Favorite"("userId","channelId");CREATE INDEX "Favorite_userId_createdAt_idx" ON "Favorite"("userId","createdAt");CREATE UNIQUE INDEX "WatchProgress_userId_mediaTitleId_key" ON "WatchProgress"("userId","mediaTitleId");CREATE UNIQUE INDEX "WatchProgress_userId_episodeId_key" ON "WatchProgress"("userId","episodeId");CREATE UNIQUE INDEX "WatchProgress_userId_channelId_key" ON "WatchProgress"("userId","channelId");CREATE INDEX "WatchProgress_userId_lastWatchedAt_idx" ON "WatchProgress"("userId","lastWatchedAt");CREATE UNIQUE INDEX "SearchHistory_userId_normalizedQuery_key" ON "SearchHistory"("userId","normalizedQuery");CREATE INDEX "SearchHistory_userId_searchedAt_idx" ON "SearchHistory"("userId","searchedAt");CREATE UNIQUE INDEX "PopularityDaily_mediaTitleId_day_key" ON "PopularityDaily"("mediaTitleId","day");CREATE INDEX "PopularityDaily_day_score_idx" ON "PopularityDaily"("day","score");
ALTER TABLE "Favorite" ADD CONSTRAINT "Favorite_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Favorite" ADD CONSTRAINT "Favorite_mediaTitleId_fkey" FOREIGN KEY("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Favorite" ADD CONSTRAINT "Favorite_channelId_fkey" FOREIGN KEY("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Favorite" ADD CONSTRAINT "Favorite_one_target" CHECK(num_nonnulls("mediaTitleId","channelId")=1);
ALTER TABLE "WatchProgress" ADD CONSTRAINT "WatchProgress_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "WatchProgress" ADD CONSTRAINT "WatchProgress_mediaTitleId_fkey" FOREIGN KEY("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "WatchProgress" ADD CONSTRAINT "WatchProgress_episodeId_fkey" FOREIGN KEY("episodeId") REFERENCES "Episode"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "WatchProgress" ADD CONSTRAINT "WatchProgress_channelId_fkey" FOREIGN KEY("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "WatchProgress" ADD CONSTRAINT "WatchProgress_one_target" CHECK(num_nonnulls("mediaTitleId","episodeId","channelId")=1);
ALTER TABLE "SearchHistory" ADD CONSTRAINT "SearchHistory_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "PopularityDaily" ADD CONSTRAINT "PopularityDaily_mediaTitleId_fkey" FOREIGN KEY("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE;
